import { describe, expect, test } from "vitest";
import { filterQuery, getQuery, withQuery } from "../src";

describe("withQuery", () => {
  const tests = [
    { input: "", query: {}, out: "" },
    { input: "/", query: {}, out: "/" },
    { input: "?test", query: {}, out: "?test" },
    { input: "/?test", query: {}, out: "/?test" },
    { input: "/?test", query: { foo: "0" }, out: "/?test&foo=0" },
    { input: "/?test", query: { foo: 0 }, out: "/?test&foo=0" },
    { input: "/?test", query: { foo: 1 }, out: "/?test&foo=1" },
    { input: "/?test", query: { test: undefined }, out: "/" },
    { input: "/?foo=1", query: { foo: 2 }, out: "/?foo=2" },
    {
      input: "/?foo=1",
      query: { foo: true, bar: false },
      out: "/?foo=true&bar=false",
    },
    { input: "/?foo=1", query: { foo: undefined }, out: "/" },
    { input: "/?foo=1", query: { foo: null }, out: "/?foo" },
    {
      input: "/",
      query: { email: "some email.com" },
      out: "/?email=some+email.com",
    },
    {
      input: "/",
      query: { "key with space": "spaced value" },
      out: "/?key+with+space=spaced+value",
    },
    {
      input: "/",
      query: { str: "&", str2: "%26" },
      out: "/?str=%26&str2=%2526",
    },
    { input: "/?x=1,2,3", query: { y: "1,2,3" }, out: "/?x=1,2,3&y=1,2,3" },
    { input: "http://a.com?v=1", query: { x: 2 }, out: "http://a.com?v=1&x=2" },
    {
      input: "/",
      query: { json: '{"test":["content"]}' },
      out: "/?json=%7B%22test%22:%5B%22content%22%5D%7D",
    },
    { input: "/", query: { param: ["3", ""] }, out: "/?param=3&param=" },
    { input: "/", query: { param: ["", "3"] }, out: "/?param=&param=3" },
    {
      input: "/",
      query: { param: { a: { nested: { object: 123 } } } },
      out: "/?param=%7B%22a%22:%7B%22nested%22:%7B%22object%22:123%7D%7D%7D",
    },
    {
      input: "/",
      query: { param: { a: [{ obj: 1 }, { obj: 2 }] } },
      out: "/?param=%7B%22a%22:%5B%7B%22obj%22:1%7D,%7B%22obj%22:2%7D%5D%7D", // {"a":[{"obj":1},{"obj":2}]}
    },
    {
      input: "/",
      query: { param: { a: [{ obj: [1, 2, 3] }] } },
      out: "/?param=%7B%22a%22:%5B%7B%22obj%22:%5B1,2,3%5D%7D%5D%7D", // {"a":[{"obj":[1,2,3]}]}
    },
    {
      input: "/",
      query: { a: "X", "b[]": [], c: "Y" },
      out: "/?a=X&c=Y",
    },
  ];

  for (const t of tests) {
    test(t.input.toString() + " with " + JSON.stringify(t.query), () => {
      expect(withQuery(t.input, t.query)).toBe(t.out);
    });
  }
});

describe("filterQuery", () => {
  const tests = [
    { input: "/foo", out: "/foo" },
    { input: "/foo?bar=1", out: "/foo" },
    { input: "/foo?bar=1&baz=2", out: "/foo?baz=2" },
  ];
  const predicate = (key: string) => key !== "bar";

  for (const t of tests) {
    test(t.input.toString() + ' filter "bar"', () => {
      expect(filterQuery(t.input, predicate)).toBe(t.out);
    });
  }
});

describe("getQuery", () => {
  const tests = {
    "http://foo.com/foo?test=123&unicode=%E5%A5%BD": {
      test: "123",
      unicode: "好",
    },
    "http://foo.com/?param=3&param=": { param: ["3", ""] },
    "http://foo.com/?param=&param=3": { param: ["", "3"] },
    "http://foo.com/?param=": { param: "" },
    "http://foo.com/?param=&param=2&param=3": { param: ["", "2", "3"] },
    "http://foo.com/?param=%7B%22a%22:%5B%7B%22obj%22:%5B1,2,3%5D%7D%5D%7D": {
      param: '{"a":[{"obj":[1,2,3]}]}',
    },
    "http://foo.com/?toString=foo": { toString: "foo" },
  };

  for (const t in tests) {
    test(t, () => {
      expect(getQuery(t)).toMatchObject(tests[t]);
    });
  }
});

test/url.test.ts.source:
import { describe, expect, test } from "vitest";
import { $URL } from "../src";

describe("$URL", () => {
  test("getters", () => {
    const inputURL =
      "https://john:doe@example.com:1080/path?query=value&v=1&v=2#hash";
    const url = new $URL(inputURL);

    expect(url.href).toEqual(inputURL);
    expect(url.toString()).toEqual(url.href);
    expect(url.toJSON()).toEqual(url.href);

    expect(url.searchParams.toString()).toEqual("query=value&v=1&v=2");
    expect(url.query).toMatchObject({ query: "value", v: ["1", "2"] });

    expect(url).toMatchObject({
      protocol: "https:",
      host: "example.com:1080",
      auth: "john:doe",
      pathname: "/path",
      hash: "#hash",
      hostname: "example.com",
      port: "1080",
      username: "john",
      password: "doe",
      hasProtocol: 6,
      isAbsolute: 6,
      search: "?query=value&v=1&v=2",
      origin: "https://example.com:1080",
      fullpath: "/path?query=value&v=1&v=2#hash",
      encodedAuth: "john:doe",
    });
  });

  test("append", () => {
    const url = new $URL(
      "https://john:doe@example.com:1080/path?query=value#hash",
    );
    const path = new $URL("/newpath?newquery=newvalue#newhash");

    url.append(path);

    expect(url.toString()).toEqual(
      "https://john:doe@example.com:1080/path/newpath?query=value&newquery=newvalue#newhash",
    );
  });

  test("throws error if appending with another url with protocol", () => {
    const url = new $URL("https://example.com/path");
    expect(() => url.append(url)).toThrow("Cannot append a URL with protocol");
  });

  describe("constructor errors", () => {
    const tests = [
      {
        input: null,
        out: "URL input should be string received object (null)",
      },
      {
        input: 123,
        out: "URL input should be string received number (123)",
      },
      {
        input: {},
        out: "URL input should be string received object ([object Object])",
      },
    ];

    for (const t of tests) {
      test(t.input + " throw", () => {
        expect(() => new $URL(t.input as any)).toThrow(new TypeError(t.out));
      });
    }
  });
});

test/join.test.ts.source:
import { describe, expect, test } from "vitest";
import { joinURL, joinRelativeURL } from "../src";

const joinURLTests = [
  { input: [], out: "" },
  { input: ["/"], out: "/" },
  { input: [undefined, "./"], out: "./" },
  { input: ["./", "a"], out: "./a" },
  { input: ["./a", "./b"], out: "./a/b" },
  { input: ["/a"], out: "/a" },
  { input: ["a", "b"], out: "a/b" },
  { input: ["/", "/b"], out: "/b" },
  { input: ["a", "b/", "c"], out: "a/b/c" },
  { input: ["a", "b/", "/c"], out: "a/b/c" },
  { input: ["/", "./"], out: "/" },
  { input: ["/", "./foo"], out: "/foo" },
  { input: ["/", "./foo/"], out: "/foo/" },
  { input: ["/", "./foo", "bar"], out: "/foo/bar" },
  {
    input: ["https://google.com/", "./foo", "/bar"],
    out: "https://google.com/foo/bar",
  },
  {
    input: ["//google.com/", "./foo", "/bar"],
    out: "//google.com/foo/bar",
  },
] as const;

describe("joinURL", () => {
  for (const t of joinURLTests) {
    test(`joinURL(${t.input.map((i) => JSON.stringify(i)).join(", ")}) === ${JSON.stringify(t.out)}`, () => {
      expect(joinURL(...(t.input as any[]))).toBe(t.out);
    });
  }
});

describe("joinRelativeURL", () => {
  const relativeTests = [
    ...joinURLTests,
    // Relative with ../
    { input: ["/a", "../b"], out: "/b" },
    { input: ["/a/b/c", "../../d"], out: "/a/d" },
    { input: ["/a", "../../d"], out: "/d" },
    { input: ["/a", ".././../d"], out: "/d" },
    { input: ["/a", "../../../d"], out: "../d" },
    { input: ["/a/b", "../../../d"], out: "/d" },
    { input: ["../a", "../b"], out: "b" },
    { input: ["../a", "./../b"], out: "b" },
    { input: ["../a", "./../../b"], out: "../b" },
    { input: ["../a", "../../../b"], out: "../../b" },
    { input: ["../a", "../../../../b"], out: "../../../b" },
    { input: ["../a/", "../b"], out: "b" },
    {
      input: ["https://google.com/", "../foo"],
      out: "https://google.com/foo",
    },
  ];

  for (const t of relativeTests) {
    test(`joinRelativeURL(${t.input.map((i) => JSON.stringify(i)).join(", ")}) === ${JSON.stringify(t.out)}`, () => {
      expect(joinRelativeURL(...(t.input as string[]))).toBe(t.out);
    });
  }
});

test/trailing-slash.test.ts.source:
import { describe, expect, test } from "vitest";
import { withTrailingSlash, withoutTrailingSlash } from "../src";

describe("withTrailingSlash, queryParams: false", () => {
  const tests = {
    "": "/",
    bar: "bar/",
    "bar#abc": "bar#abc/",
    "bar/": "bar/",
    "foo?123": "foo?123/",
    "foo/?123": "foo/?123/",
    "foo/?123#abc": "foo/?123#abc/",
  };

  for (const input in tests) {
    test(input, () => {
      expect(withTrailingSlash(input)).toBe(tests[input]);
    });
  }

  test("falsy value", () => {
    expect(withTrailingSlash()).toBe("/");
  });
});

describe("withTrailingSlash, queryParams: true", () => {
  const tests = {
    "": "/",
    bar: "bar/",
    "bar/": "bar/",
    "foo?123": "foo/?123",
    "foo/?123": "foo/?123",
    "foo?123#abc": "foo/?123#abc",
    "/#abc": "/#abc",
    "#abc": "#abc",
    "#": "#",
  };

  for (const input in tests) {
    test(input, () => {
      expect(withTrailingSlash(input, true)).toBe(tests[input]);
    });
  }

  test("falsy value", () => {
    expect(withTrailingSlash()).toBe("/");
  });
});

describe("withoutTrailingSlash, queryParams: false", () => {
  const tests = {
    "": "/",
    "/": "/",
    bar: "bar",
    "bar#abc": "bar#abc",
    "bar/#abc": "bar/#abc",
    "foo?123": "foo?123",
    "foo/?123": "foo/?123",
    "foo/?123#abc": "foo/?123#abc",
    "foo/?k=v": "foo/?k=v",
    "foo/?k=/": "foo/?k=",
  };

  for (const input in tests) {
    test(input, () => {
      expect(withoutTrailingSlash(input)).toBe(tests[input]);
    });
  }

  test("falsy value", () => {
    expect(withoutTrailingSlash()).toBe("/");
  });
});

describe("withoutTrailingSlash, queryParams: true", () => {
  const tests = {
    "": "/",
    "/": "/",
    bar: "bar",
    "bar/": "bar",
    "bar#abc": "bar#abc",
    "bar/#abc": "bar#abc",
    "foo?123": "foo?123",
    "foo/?123": "foo?123",
    "foo/?123#abc": "foo?123#abc",
    "foo/?k=123": "foo?k=123",
    "foo?k=/": "foo?k=/",
    "foo/?k=/": "foo?k=/",
    "foo/?k=/&x=y#abc": "foo?k=/&x=y#abc",
    "/a/#abc": "/a#abc",
    "/#abc": "/#abc",
  };

  for (const input in tests) {
    test(input, () => {
      expect(withoutTrailingSlash(input, true)).toBe(tests[input]);
    });
  }

  test("falsy value", () => {
    expect(withoutTrailingSlash()).toBe("/");
  });
});

test/base.test.ts.source:
import { describe, expect, test } from "vitest";
import { withBase, withoutBase } from "../src";

describe("withBase", () => {
  const tests = [
    { base: "/", input: "/", out: "/" },
    { base: "/foo", input: "", out: "/foo" },
    { base: "/foo/", input: "/", out: "/foo" },
    { base: "/foo", input: "/bar", out: "/foo/bar" },
    { base: "/base/", input: "/base", out: "/base" },
    { base: "/base", input: "/base/", out: "/base/" },
    { base: "/base", input: "/base/a", out: "/base/a" },
    { base: "/base/", input: "/base/a", out: "/base/a" },
    { base: "/base/", input: "https://test.com", out: "https://test.com" },
    { base: "/", input: "https://test.com", out: "https://test.com" },
    {
      base: "/admin/",
      input: "/admin-dashboard",
      out: "/admin/admin-dashboard",
    },
    {
      base: "/admin/",
      input: "/admin/admin-dashboard",
      out: "/admin/admin-dashboard",
    },
    {
      base: "/admin",
      input: "/admin-dashboard",
      out: "/admin/admin-dashboard",
    },
    { base: "/admin/", input: "/admin/dashboard", out: "/admin/dashboard" },
  ];

  for (const t of tests) {
    test(JSON.stringify(t.base) + " + " + JSON.stringify(t.input), () => {
      expect(withBase(t.input, t.base)).toBe(t.out);
    });
  }
});

describe("withoutBase", () => {
  const tests = [
    { base: "/", input: "/", out: "/" },
    { base: "/foo", input: "/", out: "/" },
    { base: "/foo/", input: "/", out: "/" },
    { base: "/foo", input: "/bar", out: "/bar" },
    { base: "/base/", input: "/base", out: "/" },
    { base: "/base", input: "/base/", out: "/" },
    { base: "/base", input: "/base/a", out: "/a" },
    { base: "/base/", input: "/base/a", out: "/a" },
    { base: "/base/a/", input: "/base/a", out: "/" },
    { base: "/", input: "/test/", out: "/test/" },
    { base: "/", input: "/?test", out: "/?test" },
    { base: "/api", input: "/api?test", out: "/?test" },
    { base: "/base/", input: "https://test.com", out: "https://test.com" },
    { base: "/", input: "https://test.com", out: "https://test.com" },
    { base: "/admin/", input: "/admin-dashboard", out: "/admin-dashboard" },
    {
      base: "/admin/",
      input: "/admin/admin-dashboard",
      out: "/admin-dashboard",
    },
    { base: "/admin", input: "/admin-dashboard", out: "/admin-dashboard" },
    { base: "/admin/", input: "/admin/dashboard", out: "/dashboard" },
    // Collapse leading "//" to prevent protocol-relative URL injection
    { base: "/legacy", input: "/legacy//evil.com", out: "/evil.com" },
    { base: "/legacy/", input: "/legacy//evil.com", out: "/evil.com" },
    { base: "/legacy", input: "/legacy///evil.com", out: "/evil.com" },
    { base: "/legacy", input: "/legacy//", out: "/" },
  ];

  for (const t of tests) {
    test(JSON.stringify(t.input) + "-" + JSON.stringify(t.base), () => {
      expect(withoutBase(t.input, t.base)).toBe(t.out);
    });
  }
});

test/resolve.test.ts.source:
import { describe, expect, test } from "vitest";
import { resolveURL } from "../src";

describe("resolveURL", () => {
  test.each([
    { input: [], out: "" },
    { input: ["/"], out: "/" },
    { input: ["/a"], out: "/a" },
    { input: ["a", "b"], out: "a/b" },
    { input: ["a", "b/", "c"], out: "a/b/c" },
    { input: ["a", "b/", "/c"], out: "a/b/c" },
    { input: ["/a?foo=bar#123", "b/", "c/"], out: "/a/b/c/?foo=bar#123" },
    { input: ["http://foo.com", "a"], out: "http://foo.com/a" },
    { input: ["a?x=1", "b?y=2&y=3&z=4"], out: "a/b?x=1&y=2&y=3&z=4" },
  ])("$input -> $out", (t) => {
    expect(resolveURL(...t.input)).toBe(t.out);
  });

  test("invalid URL (null)", () => {
    expect(() => resolveURL(null as any)).toThrow(
      "URL input should be string received object (null)",
    );
  });

  test("invalid URL (array)", () => {
    expect(() => resolveURL([])).toThrow(
      "URL input should be string received object ()",
    );
  });

  test("no arguments", () => {
    expect(resolveURL()).toBe("");
  });
});

test/is-same.test.ts.source:
import { describe, expect, test } from "vitest";
import { isSamePath } from "../src";

describe("isSamePath", () => {
  const samePaths = [
    ["/foo", "/foo"],
    ["/foo", "/foo/"],
    ["/", ""],
    ["/%D1%82%D0%B5%D1%81%D1%82", "/тест"],
  ];

  const notSamePaths = [["/foo", "/bar"]];

  for (const [u1, u2] of samePaths) {
    test(u1 + " == " + u2, () => {
      expect(isSamePath(u1, u2)).toBe(true);
    });
  }

  for (const [u1, u2] of notSamePaths) {
    test(u1 + " != " + u2, () => {
      expect(isSamePath(u1, u2)).toBe(false);
    });
  }
});

test/double-slash.test.ts.source:
import { describe, expect, test } from "vitest";
import { cleanDoubleSlashes } from "../src";

describe("cleanDoubleSlashes", () => {
  const tests = {
    "//foo//bar//": "/foo/bar/",
    "http://foo.com//": "http://foo.com/",
    "http://foo.com/bar//foo/": "http://foo.com/bar/foo/",
    "http://example.com/analyze//http://localhost:3000//":
      "http://example.com/analyze/http://localhost:3000/",
  };

  for (const input in tests) {
    test(input, () => {
      expect(cleanDoubleSlashes(input)).toBe(tests[input]);
    });
  }

  test("no input", () => {
    expect(cleanDoubleSlashes()).toBe("");
  });
});
